const frame=document.getElementById("content-frame");
const loader=document.getElementById("loader");
const statusText=document.getElementById("statusText");
const progressFill=document.querySelector(".progress-fill");

/* LINK SERVER */
const MAIN_SERVER="https://discord.com";

/* FIX LOAD 30 GIÂY */
const LOAD_TIME=15000;

let progress=0;

const interval=setInterval(()=>{

progress += 100/(LOAD_TIME/100);

if(progress > 100){
progress=100;
}

progressFill.style.width=progress+"%";

/* STATUS ĐỘNG */
if(progress < 25){
statusText.innerHTML='Đang kết nối máy chủ<span class="dot">.</span><span class="dot">.</span><span class="dot">.</span>';
}
else if(progress < 50){
statusText.innerHTML='Đang đồng bộ dữ liệu<span class="dot">.</span><span class="dot">.</span><span class="dot">.</span>';
}
else if(progress < 80){
statusText.innerHTML='Đang tải hệ thống bảo mật<span class="dot">.</span><span class="dot">.</span><span class="dot">.</span>';
}
else{
statusText.innerHTML='Chuẩn bị vào máy chủ chính<span class="dot">.</span><span class="dot">.</span><span class="dot">.</span>';
}

},100);

/* SAU 30 GIÂY MỚI CHO VÀO */
setTimeout(()=>{

clearInterval(interval);

frame.src=MAIN_SERVER;

frame.onload=()=>{

loader.classList.add("fade-out");

setTimeout(()=>{

loader.style.display="none";
frame.style.display="block";

setTimeout(()=>{
frame.classList.add("visible");
},100);

},600);

};

},LOAD_TIME);
